sys_ux_data_broker_transform.script:
function transform(input) { 
    var kpiProperties = [
        'custombulk.property'
    ];

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);
        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.error("Error parsing " + propertyName + ": " + e.message);
            }
        }
        return kpis;
    }

    function getTasksByProperty() {
        var result = [];

        for (var i = 0; i < kpiProperties.length; i++) {
            var propertyName = kpiProperties[i];
            var kpis = fetchKPIs(propertyName);
            var additionalFields = [];

            for (var j = 0; j < kpis.length; j++) {
                var kpi = kpis[j];

                if (kpi.description) {
                    var taskGr = new GlideRecord('samp_sp_vb_task');
                    taskGr.addEncodedQuery('stateNOT IN-5,3,7');
                    taskGr.addQuery('description', kpi.description);
                    taskGr.query();

                    while (taskGr.next()) {
                        additionalFields.push({
                            sys_id: taskGr.getUniqueValue(),
                            description: taskGr.getValue("description"),
                            short_description: taskGr.getValue("short_description"),
                            task_number: taskGr.getValue("number")
                        });
                    }
                }
            }

            if (additionalFields.length > 0) {
                result.push({
                    additionalFields: additionalFields
                });
            }
        }

        return result;
    }

    return getTasksByProperty();
}
